//! Lattice ECP5 chip data as checked-in Rust.
//!
//! [`tiles`] has one module per tile type with its routing muxes, enums, words
//! and fixed connections; [`devices`] has each device's tile grid, clock
//! landmarks and package pins. Both are generated by `oxibit-arch-gen`
//! (`cargo run -p oxibit-arch-gen --example gen_ecp5`); `--check` compares them
//! with a fresh generation.

pub mod devices;
pub mod tiles;

use oxibit_arch::lit::{DeviceLit, TileTypeLit};

/// The tile type named `name`, such as `PLC2`.
#[must_use]
pub fn tile_type(name: &str) -> Option<&'static TileTypeLit> {
    let all = tiles::ALL;
    all.binary_search_by(|t| t.name.cmp(name)).ok().map(|i| all[i])
}

/// The device named `name`, such as `LFE5U-85F`.
#[must_use]
pub fn device(name: &str) -> Option<&'static DeviceLit> {
    devices::ALL.iter().copied().find(|d| d.name == name)
}
